const isPalindrome = (str) => {
  const originalString = `${str}`;

  const cleanedString = str
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');

  const reversedString = [...cleanedString].reverse().join('');

  const comparisonResult = cleanedString === reversedString;

  console.log(`Original string: ${originalString}`);
  console.log(`Cleaned string: ${cleanedString}`);
  console.log(`Reversed string: ${reversedString}`);
  console.log(`Is it a palindrome? ${comparisonResult}`);

  if (comparisonResult) {
    console.log(`"${originalString}" IS a palindrome.`);
  } else {
    console.log(`"${originalString}" is NOT a palindrome.`);
  }

  const finalMessage = `The function processed input "${originalString}" and returned ${comparisonResult}.`;
  console.log(finalMessage);

  return comparisonResult;
};

