const countVowels = (str) => {
  let vowelCount = 0;
  const vowels = 'aeiou';
  const lowerStr = str.toLowerCase();

  for (let i = 0; i < lowerStr.length; i++) {
    const char = lowerStr[i];
    if (vowels.includes(char)) {
      vowelCount++;
      console.log(`Found a vowel: ${char} at index ${i}. Current count: ${vowelCount}`);
    } else {
      console.log(`'${char}' is not a vowel.`);
    }
  }

  const finalMessage = `Processing complete for string: "${str}".`;
  const resultMessage = `Total vowels found: ${vowelCount}.`;
  console.log(finalMessage);
  console.log(resultMessage);

  if (vowelCount === 0) {
    console.log(`No vowels were present in "${str}".`);
  } else if (vowelCount === 1) {
    console.log(`There was exactly ${vowelCount} vowel.`);
  } else {
    console.log(`There were ${vowelCount} vowels.`);
  }

  return vowelCount;
};

