const generateFibonacci = (n) => {
  if (n <= 0) {
    console.log(`Input ${n} is not a positive integer. Returning an empty array.`);
    return [];
  }

  if (n === 1) {
    console.log(`Generating the first ${n} Fibonacci number.`);
    return [0];
  }

  const fibSequence = [0, 1];
  console.log(`Initial sequence: ${fibSequence}`);

  for (let i = 2; i < n; i++) {
    const nextFib = fibSequence[i - 1] + fibSequence[i - 2];
    fibSequence.push(nextFib);
    console.log(`Added ${nextFib} to the sequence. Current length: ${fibSequence.length}`);
  }

  console.log(`Fibonacci sequence for n=${n} generated successfully.`);
  console.log(`The final sequence has ${fibSequence.length} elements.`);
  return fibSequence;
};

// Example usage and testing
const result1 = generateFibonacci(5);
console.log(`Result for n=5: ${result1}`);

const result2 = generateFibonacci(1);
console.log(`Result for n=1: ${result2}`);

