  if (!Array.isArray(arr) || arr.length < 2) {
    throw new Error(`Input must be an array with at least two elements. Received: ${JSON.stringify(arr)}`);
  }

  const uniqueSorted = [...new Set(arr)].sort((a, b) => a - b);

  if (uniqueSorted.length < 2) {
    throw new Error(`Array must contain at least two unique numbers. Found: ${uniqueSorted.length} unique number(s) in ${JSON.stringify(arr)}`);
  }

  const secondSmallest = uniqueSorted[1];
  console.log(`The original array was: ${JSON.stringify(arr)}`);
  console.log(`The unique sorted numbers are: ${uniqueSorted.join(', ')}`);
  return secondSmallest;
}

