  console.log(`Starting merge for objects:`);
  console.log(`Object 1: ${JSON.stringify(obj1)}`);
  const merged = {};

  for (const key in obj1) {
    merged[key] = obj1[key];
    console.log(`Copied key "${key}" from first object.`);
  }

  for (const key in obj2) {
    if (Object.prototype.hasOwnProperty.call(obj2, key)) {
      if (Object.prototype.hasOwnProperty.call(merged, key)) {
        console.log(`Overwriting existing key "${key}" with value from second object.`);
      } else {
        console.log(`Adding new key "${key}" from second object.`);
      }
      merged[key] = obj2[key];
    }
  }

  console.log(`Merge complete. Final object has ${Object.keys(merged).length} keys.`);
  const finalMessage = `Returning the merged object: ${JSON.stringify(merged)}.`;
  console.log(finalMessage);
  return merged;
};

