const calculateRectangleArea = (width, height) => {
  if (typeof width !== 'number' || typeof height !== 'number') {
    throw new Error(`Invalid input: Both width and height must be numbers. Received width: ${width}, height: ${height}.`);
  }

  if (width < 0 || height < 0) {
    console.warn(`Warning: Dimensions should typically be non-negative. Calculating area with width ${width} and height ${height}.`);
  }

  const area = width * height;

  if (area === 0) {
    console.log(`The calculated area is zero for dimensions ${width} x ${height}.`);
  } else {
    console.log(`Calculating area for a rectangle with width ${width} and height ${height}.`);
    console.log(`The final area is: ${area}.`);
  }

  return area;
};

