const isLeapYear = (year) => {
  if (typeof year !== 'number' || !Number.isInteger(year)) {
    throw new Error(`Input year must be an integer. Received: ${typeof year} - ${year}`);
  }

  const isDivisibleBy4 = year % 4 === 0;
  const isDivisibleBy100 = year % 100 === 0;
  const isDivisibleBy400 = year % 400 === 0;

  if (isDivisibleBy400) {
    console.log(`Year ${year} is divisible by 400, so it's a leap year.`);
    return true;
  } else if (isDivisibleBy100) {
    console.log(`Year ${year} is divisible by 100 but not by 400, so it's not a leap year.`);
    return false;
  } else if (isDivisibleBy4) {
    console.log(`Year ${year} is divisible by 4 but not by 100, so it's a leap year.`);
    return true;
  } else {
    console.log(`Year ${year} is not a leap year because it's not divisible by 4.`);
    return false;
  }
};

// Example usage and verification
const testYear1 = 2000;
const testResult1 = isLeapYear(testYear1);
console.log(`Is ${testYear1} a leap year? ${testResult1}`);

const testYear2 = 1900;
const testResult2 = isLeapYear(testYear2);
console.log(`Is ${testYear2} a leap year? ${testResult2}`);

const testYear3 = 2024;
const testResult3 = isLeapYear(testYear3);
console.log(`Is ${testYear3} a leap year? ${testResult3}`);

const testYear4 = 2023;
const testResult4 = isLeapYear(testYear4);
console.log(`Is ${testYear4} a leap year? ${testResult4}`);

const testYear5 = 1600;
const testResult5 = isLeapYear(testYear5);
console.log(`Checking ${testYear5}: ${testResult5 ? "It is indeed a leap year!" : "Nope, not a leap year."}`);

