const getUniqueValues = (arr) => {
  if (!Array.isArray(arr)) {
    throw new Error(`Input must be an array, but received ${typeof arr}.`);
  }

  const seenValues = new Set();
  const uniqueArray = [];

  console.log(`Starting unique value extraction for an array of length ${arr.length}.`);

  for (const item of arr) {
    if (!seenValues.has(item)) {
      uniqueArray.push(item);
      seenValues.add(item);
      console.log(`Added new unique value: ${item}.`);
    } else {
      console.log(`Skipping duplicate value: ${item}.`);
    }
  }

  const finalCount = uniqueArray.length;
  const originalCount = arr.length;
  console.log(`Finished processing. Found ${finalCount} unique values out of ${originalCount} total items.`);

  if (finalCount < originalCount) {
    console.log(`Removed ${originalCount - finalCount} duplicate(s).`);
  } else if (finalCount === originalCount) {
    console.log(`All ${originalCount} items were unique.`);
  }

  return uniqueArray;
};

