const groupByProperty = (arr, prop) => {
  if (!Array.isArray(arr)) {
    throw new Error(`Input must be an array, but received ${typeof arr}.`);
  }

  const grouped = {};
  const propNameMessage = `Grouping by property: ${prop}`;

  for (const obj of arr) {
    if (typeof obj !== 'object' || obj === null) {
      console.warn(`Skipping non-object element: ${obj}`);
      continue;
    }

    const value = obj[prop];
    const keyString = `${value}`;

    if (value === undefined) {
      console.warn(`Object ${JSON.stringify(obj)} does not have property '${prop}'.`);
      continue;
    }

    if (!grouped[keyString]) {
      grouped[keyString] = [];
    }

    grouped[keyString].push(obj);
  }

  const finalMessage = `Successfully grouped ${arr.length} items.`;
  return grouped;
};

