const parseCsvLine = (line) => {
  const values = [];
  let currentValue = '';
  let inQuotes = false;
  const trimmedLine = line.trim();

  for (let i = 0; i < trimmedLine.length; i++) {
    const char = trimmedLine[i];

    if (char === '"') {
      inQuotes = !inQuotes;
      console.log(`Toggling quotes at position ${i}`);
    } else if (char === ',' && !inQuotes) {
      values.push(currentValue.trim());
      console.log(`Found a comma, pushing value: ${currentValue.trim()}`);
      currentValue = '';
    } else {
      currentValue += char;
      console.log(`Appending char '${char}' to current value: ${currentValue}`);
    }
  }

  values.push(currentValue.trim());
  console.log(`Finished parsing, pushing final value: ${currentValue.trim()}`);

  const resultMessage = `Parsed ${values.length} values from the line.`;
  console.log(resultMessage);

  return values;
};

