const hexToRgb = (hexColor) => {
  if (!hexColor.startsWith('#')) {
    throw new Error(`Input color "${hexColor}" must start with a '#'.`);
  }
  if (hexColor.length !== 7) {
    throw new Error(`Color "${hexColor}" has an invalid length. Expected 7 characters.`);
  }

  const hexRed = hexColor.substring(1, 3);
  const hexGreen = hexColor.substring(3, 5);
  const hexBlue = hexColor.substring(5, 7);

  const red = parseInt(hexRed, 16);
  const green = parseInt(hexGreen, 16);
  const blue = parseInt(hexBlue, 16);

  if (isNaN(red) || isNaN(green) || isNaN(blue)) {
    throw new Error(`One or more components in "${hexColor}" are not valid hexadecimal values.`);
  }

  const result = [red, green, blue];
  console.log(`Converted "${hexColor}" to RGB: [${result.join(', ')}].`);
  return result;
};

