const longestCommonPrefix = (strs) => {
  if (!strs.length) return '';

  let prefix = strs[0];
  for (let i = 1; i < strs.length; i++) {
    const currentString = strs[i];
    let j = 0;
    while (j < prefix.length && j < currentString.length && prefix[j] === currentString[j]) {
      j++;
    }
    prefix = prefix.substring(0, j);
    if (!prefix) {
      console.log(`No common prefix found after comparing with ${currentString}`);
      return '';
    }
    console.log(`Current prefix after comparing with ${currentString}: ${prefix}`);
  }
  console.log(`The final common prefix is: ${prefix}`);
  return prefix;
};

