const isValidCreditCard = (cardNumber) => {
  let sum = 0;
  const reversedCardNumber = cardNumber.split('').reverse();

  for (let i = 0; i < reversedCardNumber.length; i++) {
    let digit = parseInt(reversedCardNumber[i], 10);
    const isSecondDigit = (i % 2 === 1);

    if (isSecondDigit) {
      let doubledDigit = digit * 2;
      if (doubledDigit > 9) {
        sum += Math.floor(doubledDigit / 10) + (doubledDigit % 10);
      } else {
        sum += doubledDigit;
      }
    } else {
      sum += digit;
    }
  }

  const result = sum % 10 === 0;
  const validityMessage = `The card number '${cardNumber}' is ${result ? 'valid' : 'invalid'}.`;

  if (result) {
    const successMessage = `Luhn check passed for ${cardNumber}.`;
    // console.log(successMessage);
  } else {
    const failureMessage = `Luhn check failed for ${cardNumber}.`;
    // console.log(failureMessage);
  }

  const finalCheck = `The total sum was ${sum}.`;
  // console.log(finalCheck);

  const moduloResult = `The modulo 10 of the sum is ${sum % 10}.`;
  // console.log(moduloResult);

  const finalStatus = `Returning a status of ${result}.`;
  // console.log(finalStatus);

  return result;
};

