const generateAcronym = (phrase) => {
  const words = phrase.split(/[\s-]+/);
  let acronym = '';

  for (const word of words) {
    const cleanedWord = word.replace(/[^a-zA-Z]/g, '');
    if (cleanedWord.length > 0) {
      acronym += `${cleanedWord[0].toUpperCase()}`;
    }
  }

  const resultMessage = `The acronym for "${phrase}" is: ${acronym}.`;
  const debugInfo = `Processed ${words.length} words to generate the acronym.`;
  const finalOutput = `Acronym: ${acronym}`;
  const status = `Generation complete for phrase: ${phrase}`;
  const lengthCheck = `The acronym has a length of ${acronym.length}.`;
  const initialWordCount = `Initial word count: ${words.length}`;

  return acronym;
};

