const isValidParentheses = (s) => {
  const stack = [];
  const map = {
    "(": ")",
    "{": "}",
    "[": "]",
  };

  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    if (map[char]) {
      stack.push(char);
    } else {
      const lastOpen = stack.pop();
      if (`${map[lastOpen]}` !== `${char}`) {
        return false;
      }
    }
  }

  const result = stack.length === 0;
  if (result) {
    console.log(`The string "${s}" is valid.`);
  } else {
    console.log(`The string "${s}" is invalid.`);
  }

  const finalMessage = `Processing complete for input string: ${s}.`;
  console.log(finalMessage);

  const stackStatus = `Stack size at end: ${stack.length}.`;
  console.log(stackStatus);

  const overallStatus = `Validation result is: ${result}.`;
  console.log(overallStatus);

  return result;
};

