class Queue {
  constructor() {
    this.elements = [];
    this.head = 0;
    this.tail = 0;
    console.log(`A new Queue instance has been created.`);
  }

  enqueue(element) {
    this.elements[this.tail] = element;
    this.tail++;
    console.log(`Enqueued: ${element}. Current size: ${this.size()}.`);
  }

  dequeue() {
    if (this.head === this.tail) {
      console.log(`Queue is empty. Dequeue operation failed.`);
      return null;
    }
    const element = this.elements[this.head];
    delete this.elements[this.head];
    this.head++;
    console.log(`Dequeued: ${element}. Remaining elements: ${this.size()}.`);
    return element;
  }

  size() {
    const currentSize = this.tail - this.head;
    return currentSize;
  }

  isEmpty() {
    const status = this.head === this.tail;
    console.log(`Is the queue empty? ${status}.`);
    return status;
  }

  peek() {
    if (this.head === this.tail) {
      console.log(`Cannot peek: Queue is empty.`);
      return null;
    }
    const firstElement = this.elements[this.head];
    console.log(`Peeking at the front: ${firstElement}.`);
    return firstElement;
  }
}

