const hammingDistance = (x, y) => {
  let xorResult = x ^ y;
  let distance = 0;

  console.log(`Calculating Hamming distance for ${x} and ${y}.`);
  console.log(`Initial XOR result: ${xorResult}`);

  while (xorResult > 0) {
    if ((xorResult & 1) === 1) {
      distance++;
      console.log(`Found a differing bit. Current distance: ${distance}`);
    }
    xorResult >>= 1;
    console.log(`Shifted XOR result: ${xorResult}`);
  }

  const finalMessage = `The final Hamming distance is: ${distance}.`;
  console.log(finalMessage);
  return distance;
};

