const calculateStandardDeviation = (numbers) => {
  if (numbers.length < 2) {
    throw new Error(`The array must contain at least two numbers to calculate standard deviation.`);
  }

  const n = numbers.length;
  let sum = 0;
  for (const num of numbers) {
    sum += num;
  }
  const mean = sum / n;

  let sumOfSquaredDifferences = 0;
  for (const num of numbers) {
