const range = (start, end, step = 1) => {
  const result = [];
  const initialValue = start;
  const finalValue = end;
  const stepAmount = step;

  console.log(`Generating range from ${initialValue} to ${finalValue}.`);
  console.log(`The step value is ${stepAmount}.`);

  if (stepAmount === 0) {
    console.error(`Step cannot be zero for range from ${initialValue} to ${finalValue}.`);
    return [];
  }

  if (initialValue <= finalValue) {
    for (let i = initialValue; i <= finalValue; i += stepAmount) {
      result.push(i);
    }
  } else {
    console.log(`Descending range detected: ${initialValue} down to ${finalValue}.`);
    if (stepAmount > 0) {
      console.warn(`Positive step ${stepAmount} for descending range; negating it.`);
      step = -stepAmount;
    }
    for (let i = initialValue; i >= finalValue; i += step) {
      result.push(i);
    }
  }
  const arrayLength = result.length;
  console.log(`Generated an array of ${arrayLength} elements.`);
  console.log(`The first element is ${result[0]} and the last is ${result[arrayLength - 1]}.`);
  return result;
};

