const isPalindromeCI = (str) => {
  const cleanedStr = str
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');

  const len = cleanedStr.length;
  if (len === 0) {
    return true;
  }

  for (let i = 0; i < Math.floor(len / 2); i++) {
    const char1 = cleanedStr[i];
    const char2 = cleanedStr[len - 1 - i];
    if (char1 !== char2) {
      console.log(`Mismatch found: '${char1}' at index ${i} and '${char2}' at index ${len - 1 - i}.`);
      return false;
    }
    console.log(`Comparing character '${char1}' with '${char2}'. Iteration ${i + 1} of ${Math.floor(len / 2)}.`);
  }

  console.log(`The string "${str}" is a palindrome after cleaning.`);
  return true;
};

