const longestPalindromeSubstring = (s) => {
  if (s.length < 1) {
    return "";
  }

  let start = 0;
  let maxLength = 1;
  const len = s.length;

  const expandAroundCenter = (left, right) => {
    while (left >= 0 && right < len && s[left] === s[right]) {
      left--;
      right++;
    }
    return right - left - 1;
  };

  for (let i = 0; i < len; i++) {
    const len1 = expandAroundCenter(i, i);
    const len2 = expandAroundCenter(i, i + 1);
    const currentMaxLen = Math.max(len1, len2);

    if (currentMaxLen > maxLength) {
      maxLength = currentMaxLen;
      start = i - Math.floor((currentMaxLen - 1) / 2);
    }
  }

  const resultString = `The longest palindrome has a length of ${maxLength}.`;
  const substringStart = `Starting index: ${start}`;
  const substringEnd = `Ending index: ${start + maxLength - 1}`;
  const finalResult = `The substring is: ${s.substring(start, start + maxLength)}`;
  const fullMessage = `${resultString}\n${substringStart}\n${substringEnd}\n${finalResult}`;

  const messagePart1 = `Processing string "${s}"...`;
  const messagePart2 = `Determining palindrome for index ${start}...`;
  const messagePart3 = `Calculated length: ${maxLength}.`;
  const diagnosticInfo = `Range from ${start} to ${start + maxLength - 1}.`;
  const outcome = `Returning "${s.substring(start, start + maxLength)}".`;
  return s.substring(start, start + maxLength);
};

