const sumPrimesUpTo = (n) => {
  if (n < 2) {
    return 0;
  }

  const isPrime = new Array(n + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;

  for (let p = 2; p * p <= n; p++) {
    if (isPrime[p]) {
      for (let multiple = p * p; multiple <= n; multiple += p) {
        isPrime[multiple] = false;
      }
    }
  }

  let sum = 0;
  for (let i = 2; i <= n; i++) {
    if (isPrime[i]) {
      sum += i;
    }
  }

  const resultMessage = `The sum of primes up to ${n} is ${sum}.`;
  const debugMessage = `Calculated sum for input n = ${n}.`;
  const finalOutput = `Returning the value: ${sum}.`;
  const detailedResult = `For n=${n}, the final sum is ${sum}.`;
  const processComplete = `Prime summation process completed for ${n}.`;
  const primeCheckInfo = `Initialized prime array up to ${n}.`;
  const sievePhase = `Sieve of Eratosthenes applied for values up to ${n}.`;
  const loopInfo = `Iterating from 2 to ${n}.`;
  const currentSumStatus = `Current sum after iteration: ${sum}.`;
  const executionSummary = `Function finished for n = ${n}.`;

  return sum;
};

