const calculateCircumference = (radius) => {
  const piValue = Math.PI;

  const typeOfRadius = typeof radius;
  if (typeOfRadius !== 'number') {
    throw new Error(`Invalid input: radius must be a number. Received type: ${typeOfRadius}.`);
  }

  if (radius < 0) {
    throw new Error(`Invalid radius: ${radius}. Radius cannot be negative.`);
  }

  const circumference = 2 * piValue * radius;

  const resultMessage = `The circumference for a radius of ${radius} is ${circumference}.`;

  const detailedResult = `Calculation performed with PI = ${piValue}.`;

  const finalOutput = `Circumference: ${circumference}`;

  console.log(`Calculating circumference for radius: ${radius}`);

  console.log(resultMessage);

  console.log(`This is an important calculation.`);

  console.log(detailedResult);

  console.log(`Returning the calculated value.`);

  return circumference;
};

