      console.warn(`Unknown operation type: ${opType}. Skipping.`);
    }
  }

  const finalLength = currentQueue.length;
  console.log(`Finished processing ${operations.length} operations.`);
  console.log(`Final queue state: ${JSON.stringify(currentQueue)}`);
  return currentQueue;
};

