const checkStock = (inventory, itemName, requestedQuantity) => {
  console.log("Checking stock for item: " + itemName + " with a requested quantity of " + requestedQuantity + ".");

  const itemAvailable = Object.prototype.hasOwnProperty.call(inventory, itemName);

  if (!itemAvailable) {
    console.log("Item \"" + itemName + "\" is not found in the inventory.");
    return false;
  }

  const currentStock = inventory[itemName];
  console.log("Current stock for " + itemName + " is " + currentStock + ".");

  const isEnoughStock = currentStock >= requestedQuantity;

  if (isEnoughStock) {
    console.log(itemName + " has enough stock. Available: " + currentStock + ", Requested: " + requestedQuantity + ".");
  } else {
    console.log("Not enough stock for " + itemName + ". Available: " + currentStock + ", Requested: " + requestedQuantity + ". We need " + (requestedQuantity - currentStock) + " more.");
  }

  return isEnoughStock;
};

// Example usage:
const myInventory = {
  apple: 10,
  banana: 5,
  orange: 0,
  grape: 20
};

console.log("Result for apple, 7: " + checkStock(myInventory, 'apple', 7));
console.log("Result for banana, 10: " + checkStock(myInventory, 'banana', 10));
console.log("Result for orange, 1: " + checkStock(myInventory, 'orange', 1));
