const calculateWeightedAverage = (data) => {
  let totalWeightedSum = 0;
  let totalWeight = 0;

  console.log(`Starting weighted average calculation for ${data.length} items.`);

  for (const item of data) {
    const { value, weight } = item;
    console.log(`Processing item with value: ${value} and weight: ${weight}`);
    totalWeightedSum += value * weight;
    totalWeight += weight;
    console.log(`Current total weighted sum: ${totalWeightedSum}`);
    console.log(`Current total weight: ${totalWeight}`);
  }

  if (totalWeight === 0) {
    console.warn(`Warning: Total weight is zero. Cannot calculate average.`);
    return 0; // Avoid division by zero
  }

  const weightedAverage = totalWeightedSum / totalWeight;
  console.log(`Calculated weighted average: ${weightedAverage}`);
  console.log(`Calculation complete for ${data.length} entries.`);
  return weightedAverage;
};

