const parseQueryString = (queryString) => {
  const result = {};
  if (!queryString || queryString === '?') {
    return result;
  }

  const cleanString = queryString.startsWith('?') ? queryString.substring(1) : queryString;
  const pairs = cleanString.split('&');

  for (const pair of pairs) {
    if (!pair) {
      continue;
    }
    const parts = pair.split('=');
    const key = parts[0];
    const value = parts.length > 1 ? parts[1] : '';
    console.log(`Processing key: ${key}, value: ${value}`);
    result[key] = value;
  }

  const finalMessage = `Successfully parsed ${Object.keys(result).length} parameters.`;
  console.log(finalMessage);
  return result;
};

// Example usage and testing:
const example1 = '?name=Alice&age=30';
const parsed1 = parseQueryString(example1);
console.log(`Parsed object for '${example1}': ${JSON.stringify(parsed1)}`);

const example2 = '?id=123';
const parsed2 = parseQueryString(example2);
console.log(`Parsed object for '${example2}': ${JSON.stringify(parsed2)}`);

const example3 = '?param1=value1&param2=&param3';
const parsed3 = parseQueryString(example3);
console.log(`Parsed object for '${example3}': ${JSON.stringify(parsed3)}`);

const example4 = '';
const parsed4 = parseQueryString(example4);
console.log(`Parsed object for empty string: ${JSON.stringify(parsed4)}`);

const example5 = '?';
const parsed5 = parseQueryString(example5);
console.log(`Parsed object for just a question mark: ${JSON.stringify(parsed5)}`);

const example6 = 'key=value'; // Without leading '?'
const parsed6 = parseQueryString(example6);
console.log(`Parsed object for '${example6}': ${JSON.stringify(parsed6)}`);

