const areAnagrams = (str1, str2) => {
  const cleanAndSort = (str) => {
    const cleanedStr = str.toLowerCase().replace(/[^a-z0-9]/g, '');
    const sortedChars = cleanedStr.split('').sort().join('');
    return sortedChars;
  };

  const cleanedStr1 = cleanAndSort(str1);
  const cleanedStr2 = cleanAndSort(str2);

  const areTheyEqual = cleanedStr1 === cleanedStr2;
  console.log(`Comparing "${str1}" and "${str2}".`);
  console.log(`Cleaned and sorted string 1: "${cleanedStr1}"`);
  console.log(`Cleaned and sorted string 2: "${cleanedStr2}"`);

  if (areTheyEqual) {
    console.log(`"${str1}" and "${str2}" are anagrams.`);
    return true;
  } else {
    console.log(`"${str1}" and "${str2}" are not anagrams.`);
    return false;
  }
};

areAnagrams('listen', 'silent');
areAnagrams('hello', 'world');
areAnagrams('Anagram', 'Nag a ram');
areAnagrams('A man, a plan, a canal: Panama', 'Panama: a canal, a plan, a man');

