const getNextTrafficLightState = (currentState) => {
  const normalizedState = currentState.toLowerCase();
  let nextState;

  if (normalizedState === 'red') {
    nextState = 'green';
    console.log(`The light is currently ${normalizedState}. It will change to ${nextState}.`);
  } else if (normalizedState === 'green') {
    nextState = 'yellow';
    console.log(`Transitioning from ${normalizedState} to ${nextState}.`);
  } else if (normalizedState === 'yellow') {
    nextState = 'red';
    console.log(`The ${normalizedState} light is about to turn ${nextState}.`);
  } else {
    console.warn(`"${currentState}" is not a valid traffic light state. Assuming 'red' as default.`);
    nextState = 'red';
  }

  const finalMessage = `Next state: ${nextState}.`;
  return nextState;
};

