const calculateSphereVolume = (radius) => {
  if (radius < 0) {
    throw new Error(`Radius cannot be negative. Received: ${radius}`);
  }

  const radiusCubed = radius ** 3;
  const piValue = Math.PI;
  const constantFactor = 4 / 3;

  const volume = constantFactor * piValue * radiusCubed;

  console.log(`Calculating volume for a sphere with radius: ${radius}`);
  console.log(`The radius cubed is: ${radiusCubed}`);
  console.log(`Using Pi as: ${piValue}`);
  console.log(`The constant factor is: ${constantFactor}`);
  console.log(`The calculated volume is: ${volume}`);

  return volume;
};

