const calculateTip = (billTotal, tipPercentage) => {
  if (typeof billTotal !== 'number' || typeof tipPercentage !== 'number') {
    throw new Error(`Invalid input: Both billTotal and tipPercentage must be numbers. Received billTotal: ${typeof billTotal}, tipPercentage: ${typeof tipPercentage}.`);
  }

  if (billTotal < 0) {
    throw new Error(`Bill total cannot be negative. Received: ${billTotal}.`);
  }

  if (tipPercentage < 0 || tipPercentage > 100) {
    throw new Error(`Tip percentage must be between 0 and 100. Received: ${tipPercentage}.`);
  }

  const tipDecimal = tipPercentage / 100;
  const tipAmount = billTotal * tipDecimal;
  const formattedTip = tipAmount.toFixed(2); 

  console.log(`Calculating tip for a bill of $${billTotal.toFixed(2)} with a ${tipPercentage}% tip.`);
  console.log(`The calculated tip amount is $${formattedTip}.`);

  return parseFloat(formattedTip);
};

