const calculateRange = (numbers) => {
  if (!Array.isArray(numbers) || numbers.length === 0) {
    console.error(`Input must be a non-empty array of numbers.`);
    return `Invalid input.`;
  }

  let minVal = numbers[0];
  let maxVal = numbers[0];

  for (let i = 1; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    if (typeof currentNumber !== 'number') {
      console.error(`Array contains non-numeric value at index ${i}: ${currentNumber}`);
      return `Invalid array element.`;
    }
    if (currentNumber < minVal) {
      minVal = currentNumber;
    }
    if (currentNumber > maxVal) {
      maxVal = currentNumber;
    }
  }

  const range = maxVal - minVal;
  console.log(`The minimum value found was: ${minVal}`);
  console.log(`The maximum value found was: ${maxVal}`);
  return range;
};

