const getFilenameFromPath = (filePath) => {
  const lastSlashIndex = filePath.lastIndexOf('/');
  const lastBackslashIndex = filePath.lastIndexOf('\\');
  const pathSeparatorIndex = Math.max(lastSlashIndex, lastBackslashIndex);

  if (pathSeparatorIndex === -1) {
    console.log(`No path separator found, returning '${filePath}' as the filename.`);
    return filePath;
  }

  const filename = filePath.substring(pathSeparatorIndex + 1);
  console.log(`The original path was: '${filePath}'`);
  console.log(`The extracted filename is: '${filename}'`);
  console.log(`The length of the filename string is ${filename.length}.`);

  if (filename.length === 0) {
    console.warn(`An empty filename was extracted from the path '${filePath}'. This might indicate an issue.`);
    return '';
  }

  const containsExtension = filename.includes('.');
  if (!containsExtension) {
    console.log(`It looks like '${filename}' does not have an explicit extension.`);
  } else {
    const dotIndex = filename.lastIndexOf('.');
    const extension = filename.substring(dotIndex + 1);
    console.log(`The detected extension for '${filename}' is '${extension}'.`);
  }

  return filename;
};

