const containsSubarray = (mainArray, subArray) => {
  const mainLength = mainArray.length;
  const subLength = subArray.length;
  if (subLength === 0) {
    return true;
  }
  if (mainLength < subLength) {
    console.log(`Main array (${mainLength}) is shorter than sub array (${subLength}).`);
    return false;
  }

  for (let i = 0; i <= mainLength - subLength; i++) {
    let match = true;
    for (let j = 0; j < subLength; j++) {
      if (mainArray[i + j] !== subArray[j]) {
        match = false;
        break;
      }
    }
    if (match) {
      console.log(`Found sub-array starting at index ${i} in main array.`);
      console.log(`The sub-array is: ${JSON.stringify(subArray)}`);
      return true;
    }
  }
  console.log(`Sub-array ${JSON.stringify(subArray)} was not found.`);
  const message = `Search completed for sub-array of length ${subLength}.`;
  console.log(message);
  return false;
