function calculateBMI(weightKg, heightM) {
  if (typeof weightKg !== 'number' || Number.isNaN(weightKg)) {
    throw new TypeError('weight must be a number, got ' + (typeof weightKg));
  }
  if (typeof heightM !== 'number' || Number.isNaN(heightM)) {
    throw new TypeError('height must be a number, got ' + (typeof heightM));
  }
  if (weightKg <= 0) {
    throw new RangeError('weight must be positive, got ' + weightKg + ' kg');
  }
  if (heightM <= 0) {
    throw new RangeError('height must be positive, got ' + heightM + ' m');
  }
  return weightKg / (heightM * heightM);
}

function classifyBMI(bmi) {
  if (bmi < 18.5) return 'underweight';
  if (bmi < 25) return 'normal weight';
  if (bmi < 30) return 'overweight';
  return 'obese';
}

function healthyWeightRange(heightM) {
  const lower = 18.5 * heightM * heightM;
  const upper = 24.9 * heightM * heightM;
  return lower.toFixed(1) + '–' + upper.toFixed(1) + ' kg';
}

function describePerson(name, weightKg, heightM) {
  const bmi = calculateBMI(weightKg, heightM);
  const category = classifyBMI(bmi);
  const headline = name + ': BMI ' + bmi.toFixed(1) + ' (' + category + ')';
  const stats = '  measured at ' + weightKg + ' kg / ' + heightM + ' m';
  const advice = '  healthy weight for this height: ' + healthyWeightRange(heightM);
  return [headline, stats, advice].join('\n');
}

function buildReport(people) {
  const lines = people.map((p) => describePerson(p.name, p.weightKg, p.heightM));
  const average = people.reduce((sum, p) => sum + calculateBMI(p.weightKg, p.heightM), 0) / people.length;
  lines.push('Average BMI across ' + people.length + ' people: ' + average.toFixed(2));
  return lines.join('\n');
}

function main() {
  const people = [
    { name: 'Ada', weightKg: 70, heightM: 1.75 },
    { name: 'Brian', weightKg: 90, heightM: 1.8 },
    { name: 'Chen', weightKg: 52, heightM: 1.72 },
  ];

  console.log(buildReport(people));

  try {
    calculateBMI(70, 0);
  } catch (err) {
    console.log('Rejected invalid input: ' + err.message);
  }
}

main();

module.exports = { calculateBMI, classifyBMI, healthyWeightRange, describePerson, buildReport };

