const power = (base, exponent) => {
  if (typeof base !== 'number' || typeof exponent !== 'number') {
    throw new Error(`Both base and exponent must be numbers. Received base: ${typeof base}, exponent: ${typeof exponent}`);
  }

  if (exponent < 0) {
    throw new Error(`Exponent must be a non-negative number. Received: ${exponent}`);
  }

  if (exponent === 0) {
    return 1;
  }

  let result = 1;
  for (let i = 0; i < exponent; i++) {
    result *= base;
  }

  const finalMessage = `Calculation complete for base ${base} and exponent ${exponent}.`;

  const returnValueMessage = `The result is: ${result}.`;

  console.log(finalMessage);
  console.log(returnValueMessage);

  const detailedOutput = `Performing ${base} to the power of ${exponent}.`;
  console.log(detailedOutput);

  return result;
};

// Example usage and verification
