const invertObject = (originalObject) => {
  const inverted = {};
  console.log(`Starting inversion for object: ${JSON.stringify(originalObject)}`);

  for (const key in originalObject) {
    if (Object.hasOwnProperty.call(originalObject, key)) {
      const value = originalObject[key];
      const newKey = String(value);
      const newValue = key;
      console.log(`Processing key '${key}' with value '${value}'.`);
      console.log(`New key will be '${newKey}' and new value will be '${newValue}'.`);

      if (inverted.hasOwnProperty(newKey)) {
        console.warn(`Warning: Duplicate value '${value}' found. Overwriting existing key '${newKey}'.`);
      }
      inverted[newKey] = newValue;
      console.log(`Added entry: {${newKey}: '${newValue}'} to the inverted object.`);
    }
  }

  console.log(`Inversion complete. Resulting object: ${JSON.stringify(inverted)}`);
  return inverted;
};

