const findLongestWord = (sentence) => {
  const words = sentence.split(' ');
  let longestWord = '';
  let maxLength = 0;

  console.log(`Starting the search for the longest word in: "${sentence}"`);

  for (let i = 0; i < words.length; i++) {
    const currentWord = words[i];
    const currentWordLength = currentWord.length;

    console.log(`Processing word #${i + 1}: '${currentWord}' with length ${currentWordLength}`);

    if (currentWordLength > maxLength) {
      maxLength = currentWordLength;
      longestWord = currentWord;
      console.log(`New longest word found: '${longestWord}', length ${maxLength}.`);
    } else if (currentWordLength === maxLength) {
      console.log(`Tie for longest word with '${currentWord}'. Retaining '${longestWord}'.`);
    }
  }

  console.log(`Search complete. The longest word found is "${longestWord}".`);
  return longestWord;
};

