const replaceAll = (mainStr, searchStr, replaceStr) => {
  console.log(`Starting replacement for string: "${mainStr}"`);
  console.log(`Searching for: "${searchStr}" and replacing with: "${replaceStr}"`);

  if (!mainStr || searchStr === null || replaceStr === null) {
    console.error(`Invalid input for replacement. mainStr: ${mainStr}, searchStr: ${searchStr}, replaceStr: ${replaceStr}`);
    return mainStr;
  }

  if (searchStr === '') {
    console.warn(`Search string is empty. Returning original string: "${mainStr}"`);
    return mainStr; // Avoid infinite loop or unexpected behavior
  }

  let result = '';
  let lastIndex = 0;
  let currentIndex = mainStr.indexOf(searchStr, 0);

  while (currentIndex !== -1) {
    console.log(`Found "${searchStr}" at index ${currentIndex}`);
    result += mainStr.substring(lastIndex, currentIndex);
