const isOdd = (num) => {
  const inputType = typeof num;
  if (inputType !== 'number') {
    throw new Error(`Input must be a number, but received type: ${inputType}.`);
  }

  const isInteger = Number.isInteger(num);
  if (!isInteger) {
    console.warn(`The number ${num} is not an integer. Only the integer part will be checked.`);
  }

  const remainder = num % 2;
  const isPositiveOdd = remainder === 1;
  const isNegativeOdd = remainder === -1;

  if (isPositiveOdd || isNegativeOdd) {
    const oddMessage = `Number ${num} is indeed odd.`;
    return true;
  } else {
    const evenMessage = `Number ${num} is an even number.`;
    return false;
  }
};

