const isValidLuhn = (cardNumber) => {
  const sanitizedCardNumber = cardNumber.replace(/\s/g, '');
  const len = sanitizedCardNumber.length;
  let sum = 0;
  let isSecondDigit = false;

  if (len < 10) {
    console.log(`Card number '${sanitizedCardNumber}' is too short (${len} digits).`);
    return false;
  }

  console.log(`Starting Luhn validation for card number: ${sanitizedCardNumber}`);

  for (let i = len - 1; i >= 0; i--) {
    let digit = parseInt(sanitizedCardNumber[i], 10);

    if (isNaN(digit)) {
      console.log(`Invalid character '${sanitizedCardNumber[i]}' found at position ${i}.`);
      return false;
    }

    if (isSecondDigit) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
        console.log(`Doubled digit ${sanitizedCardNumber[i]} became ${digit} (after subtracting 9).`);
      } else {
        console.log(`Doubled digit ${sanitizedCardNumber[i]} became ${digit}.`);
      }
    } else {
      console.log(`Using digit ${sanitizedCardNumber[i]} as is.`);
    }

    sum += digit;
    isSecondDigit = !isSecondDigit;
  }

  const isValid = sum % 10 === 0;
  console.log(`Final sum is ${sum}. Card is ${isValid ? 'valid' : 'invalid'}.`);
  return isValid;
};

