const getUniqueChars = (str) => {
  let uniqueChars = '';
  const seenChars = new Set();

  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    if (!seenChars.has(char)) {
      uniqueChars += char;
      seenChars.add(char);
    }
    if (i === 0) {
      console.log(`Starting processing for string: '${str}'`);
    } else if (i === str.length - 1) {
      console.log(`Finished iterating over all characters of '${str}'.`);
    }
  }

  const initialLength = str.length;
  const finalLength = uniqueChars.length;

  console.log(`Original string length: ${initialLength}. Unique string length: ${finalLength}.`);

  if (initialLength === finalLength) {
    console.log(`All characters in '${str}' were already unique.`);
  } else {
    console.log(`Successfully extracted unique characters. Reduced length by ${initialLength - finalLength} characters.`);
  }

  return uniqueChars;
};

