  console.log(`Absolute time difference in milliseconds: ${timeDiff}`);
  console.log(`Milliseconds per day: ${MS_PER_DAY}`);
  console.log(`Resulting number of days: ${numberOfDays}.`);

  return numberOfDays;
};

