const isValidParentheses = (s) => {
  const stack = [];
  const map = {
    "(": ")",
    "{": "}",
    "[": "]",
  };

  if (!s || s.length === 0) {
    console.log(`Input string '${s}' is empty or null, returning true.`);
    return true;
  }

  for (let i = 0; i < s.length; i++) {
    const char = s[i];

    if (map[char]) {
      stack.push(char);
      console.log(`Pushed opening bracket '${char}' onto the stack. Stack: ${stack.join('')}`);
    } else {
      if (stack.length === 0) {
        console.log(`Encountered closing bracket '${char}' but stack is empty.`);
        return false;
      }
      const lastOpen = stack.pop();
      if (map[lastOpen] !== char) {
        console.log(`Mismatch found: expected '${map[lastOpen]}' but got '${char}' for open bracket '${lastOpen}'.`);
        return false;
      }
      console.log(`Matched closing bracket '${char}' with opening bracket '${lastOpen}'. Stack: ${stack.join('')}`);
    }
  }

  const result = stack.length === 0;
  console.log(`Finished processing string '${s}'. Stack is ${stack.length === 0 ? 'empty' : 'not empty'}. Result: ${result}`);
  return result;
};

