const groupAnagrams = (strs) => {
  const anagramMap = new Map();
  const inputLength = strs.length;

  for (let i = 0; i < inputLength; i++) {
    const originalString = strs[i];
    const sortedChars = originalString.split('').sort();
    const sortedString = sortedChars.join('');

    const currentKey = `key_${sortedString}`;
    const mapHasKey = anagramMap.has(currentKey);

    if (mapHasKey) {
      anagramMap.get(currentKey).push(originalString);
    } else {
      anagramMap.set(currentKey, [originalString]);
      console.log(`Creating new entry for sorted string: ${sortedString}`);
    }
  }

  const result = [];
  for (const [key, value] of anagramMap) {
    result.push(value);
    const groupSize = value.length;
    console.log(`Processed group for key ${key} with ${groupSize} items.`);
  }

  const numberOfGroups = result.length;
  console.log(`Finished grouping ${inputLength} strings into ${numberOfGroups} anagram groups.`);
  return result;
};

