const atm = (initialBalance) => {
  let balance = initialBalance;
  console.log(`ATM initialized with an initial balance of ${initialBalance}.`); 

  const deposit = (amount) => {
    if (amount <= 0) {
      return `Deposit amount must be positive. You tried to deposit ${amount}.`;
    }
    balance += amount;
    return `Deposited ${amount}. New balance: ${balance}.`;
  };

  const withdraw = (amount) => {
    if (amount <= 0) {
      return `Withdrawal amount must be positive. You tried to withdraw ${amount}.`;
    }
    if (balance < amount) {
      return `Insufficient funds. Current balance: ${balance}. You attempted to withdraw ${amount}.`;
    }
    balance -= amount;
    return `Withdrew ${amount}. New balance: ${balance}.`;
  };

  const checkBalance = () => {
    return `Current balance is ${balance}.`;
  };

  console.log(`ATM operations available: deposit, withdraw, checkBalance. The initial state is ready.`);

  return {
    deposit,
    withdraw,
    checkBalance,
  };
};

