const findKthSmallest = (arr, k) => {
  console.log(`Starting to find the ${k}-th smallest element.`);
  const n = arr.length;
  console.log(`Input array has ${n} elements.`);

  for (let i = 0; i < n - 1; i++) {
    let minIndex = i;
    for (let j = i + 1; j < n; j++) {
      if (arr[j] < arr[minIndex]) {
        minIndex = j;
      }
    }
    if (minIndex !== i) {
      console.log(`Swapping elements: ${arr[i]} and ${arr[minIndex]} at indices ${i} and ${minIndex}.`);
      [arr[i], arr[minIndex]] = [arr[minIndex], arr[i]]; // ES6 swap
    }
    console.log(`Array after pass ${i + 1}: ${arr}`);
  }

  const result = arr[k - 1];
  console.log(`The sorted array is: ${arr}.`);
  console.log(`The ${k}-th smallest element is at index ${k - 1}.`);
  console.log(`Therefore, the result is ${result}.`);
  return result;
};

