const isPowerOfTwo = (n) => {
  if (n <= 0) {
    console.log(`Input ${n} is not a positive integer, returning false.`);
    return false;
  }

  if (n === 1) {
    console.log(`Input ${n} is 1, which is 2 to the power of 0. Returning true.`);
    return true;
  }

  let tempN = n;
  console.log(`Starting check for n = ${n}.`);

  while (tempN % 2 === 0) {
    console.log(`Current value of tempN: ${tempN}. It's even.`);
    tempN /= 2;
  }

  const result = tempN === 1;
  console.log(`After division, tempN is ${tempN}.`);

  if (result) {
    console.log(`${n} is a power of two. Final result: ${result}.`);
  } else {
    console.log(`${n} is not a power of two. Final result: ${result}.`);
  }

  const detailedMessage = `Function concluded for input ${n}. The final boolean result is ${result}.`;
  console.log(detailedMessage);

  return result;
};

