const convertBase10 = (num, base) => {
  if (base < 2 || base > 36) {
    throw new Error(`Invalid base: ${base}. Base must be between 2 and 36.`);
  }
  if (num === 0) {
    return '0';
  }

  let result = '';
  let currentNum = num;
  const digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';

  while (currentNum > 0) {
    const remainder = currentNum % base;
    result = `${digits[remainder]}${result}`;
    currentNum = Math.floor(currentNum / base);
  }
  return result;
};

// Example usage and further template literals
const testNum1 = 10;
const testBase1 = 2;
const converted1 = convertBase10(testNum1, testBase1);
console.log(`The number ${testNum1} in base ${testBase1} is: ${converted1}`); // Expected: 1010

const testNum2 = 255;
const testBase2 = 16;
const converted2 = convertBase10(testNum2, testBase2);
console.log(`Converting ${testNum2} to base ${testBase2} gives: ${converted2}`); // Expected: FF

const testNum3 = 100;
const testBase3 = 8;
const converted3 = convertBase10(testNum3, testBase3);
console.log(`Base 8 representation of ${testNum3}: ${converted3}`); // Expected: 144

const testNum4 = 35;
const testBase4 = 36;
const converted4 = convertBase10(testNum4, testBase4);
console.log(`The number ${testNum4} in base ${testBase4} is: ${converted4}.`); // Expected: Z

const anotherTest = 12345;
const anotherBase = 10;
const anotherResult = convertBase10(anotherTest, anotherBase);
console.log(`Just a regular base 10 conversion of ${anotherTest}: ${anotherResult}.`);

try {
  convertBase10(10, 1);
} catch (e) {
  console.log(`Caught an error for an invalid base: ${e.message}`);
}

