const ipDistance = (ip1, ip2) => {
  console.log(`Calculating distance for IPs: ${ip1} and ${ip2}`);

  const parseIp = (ipString) => {
    const octets = ipString.split('.').map(Number);
    if (octets.length !== 4 || octets.some(o => isNaN(o) || o < 0 || o > 255)) {
      throw new Error(`Invalid IP address format: ${ipString}. Expected four dot-separated numbers.`);
    }
    return octets;
  };

  const octets1 = parseIp(ip1);
  const octets2 = parseIp(ip2);

  let totalDistance = 0;
  for (let i = 0; i < 4; i++) {
    const diff = Math.abs(octets1[i] - octets2[i]);
    totalDistance += diff;
    console.log(`Octet ${i + 1}: ${octets1[i]} vs ${octets2[i]}. Difference is ${diff}. Current total: ${totalDistance}.`);
  }

  console.log(`Calculation complete for ${ip1} and ${ip2}. Final distance: ${totalDistance}.`);
  return totalDistance;
};

