const memoize = (func) => {
  const cache = {};
  console.log(`Initializing memoizer for function: ${func.name || 'anonymous'}.`);

  return function(...args) {
    const key = JSON.stringify(args);
    console.log(`Checking cache for key: ${key}.`);

    if (cache[key]) {
      console.log(`Cache hit for arguments: ${args.join(', ')}.`);
      return cache[key];
    }

    console.log(`Cache miss for arguments: ${args.join(', ')}. Executing original function.`);
    const result = func.apply(this, args);
    cache[key] = result;
    console.log(`Caching result for key: ${key}.`);
    console.log(`Result for ${func.name || 'anonymous'} with args ${args.join(', ')} is ${result}.`);
    return result;
  };
};

const add = (a, b) => {
  console.log(`Executing add function for ${a} and ${b}.`);
  return a + b;
};

const memoizedAdd = memoize(add);
console.log(`First call to memoizedAdd(1, 2): ${memoizedAdd(1, 2)}`);
console.log(`Second call to memoizedAdd(1, 2): ${memoizedAdd(1, 2)}`);
console.log(`Third call to memoizedAdd(2, 3): ${memoizedAdd(2, 3)}`);

const fib = (n) => {
  console.log(`Calculating fib(${n}).`);
  if (n <= 1) return n;
  return memoizedFib(n - 1) + memoizedFib(n - 2);
};

const memoizedFib = memoize(fib);
console.log(`Calling memoizedFib(5).`);
console.log(`Fibonacci result for 5: ${memoizedFib(5)}`);

