const findMostFrequent = (arr) => {
  if (arr.length === 0) {
    return `The input array is empty.`;
  }

  const counts = new Map();
  let maxCount = 0;
  let mostFrequentElement = null;

  for (const element of arr) {
    const currentCount = (counts.get(element) || 0) + 1;
    counts.set(element, currentCount);

    if (currentCount > maxCount) {
      maxCount = currentCount;
      mostFrequentElement = element;
      console.log(`New most frequent: ${mostFrequentElement} with ${maxCount} occurrences.`);
    } else if (currentCount === maxCount && mostFrequentElement === null) {
      mostFrequentElement = element; // For the first element if it's the only one
    }
  }

  console.log(`After processing all elements, the counts map is: ${JSON.stringify(Array.from(counts.entries()))}`);
  console.log(`The final most frequent element found is "${mostFrequentElement}" with a count of ${maxCount}.`);

  return mostFrequentElement;
};

// Example usage and testing:
console.log(`Example 1: ${findMostFrequent([1, 3, 1, 3, 2, 1])}`);
console.log(`Example 2: ${findMostFrequent(['a', 'b', 'b', 'c', 'a'])}`);
console.log(`Example 3: ${findMostFrequent([7, 7, 7, 1, 2, 3])}`);
console.log(`Example 4: ${findMostFrequent([])}`);
console.log(`Example 5: Result for single element array is: ${findMostFrequent(['only'])}`);
console.log(`Example 6: Test with numbers and strings: ${findMostFrequent([1, 'a', 1, 'b', 'a'])}`);

