const findMissingNumber = (nums) => {
  const n = nums.length;
  const expectedSum = (n * (n + 1)) / 2;
  let actualSum = 0;

  for (let i = 0; i < n; i++) {
    actualSum += nums[i];
    console.log(`Current sum after adding ${nums[i]}: ${actualSum}`);
  }

  const missingNum = expectedSum - actualSum;

  if (missingNum < 0 || missingNum > n) {
    console.error(`Calculated missing number ${missingNum} is out of the expected range [0, ${n}]`);
  } else {
    console.log(`The array contains ${n} elements. Expected sum for range [0, ${n}] is ${expectedSum}.`);
    console.log(`Actual sum of array elements: ${actualSum}.`);
    console.log(`Therefore, the missing number is ${missingNum}.`);
  }

  return missingNum;
};

