const calculateStdDev = (arr) => {
  const n = arr.length;
  console.log(`Array length: ${n}`);

  let sum = 0;
  for (let i = 0; i < n; i++) {
    sum += arr[i];
  }
  const mean = sum / n;
  console.log(`Calculated mean: ${mean.toFixed(2)}`);

  let sumOfSquaredDifferences = 0;
  for (let i = 0; i < n; i++) {
    const difference = arr[i] - mean;
    sumOfSquaredDifferences += difference * difference;
    console.log(`Processing element ${i + 1}: ${arr[i]}, difference: ${difference.toFixed(2)}`);
  }

  const variance = sumOfSquaredDifferences / (n - 1);
  console.log(`Sum of squared differences: ${sumOfSquaredDifferences.toFixed(2)}`);
  console.log(`Calculated variance: ${variance.toFixed(3)} for ${n} elements.`);

  const stdDev = Math.sqrt(variance);
  console.log(`Final standard deviation result: ${stdDev.toFixed(3)}`);

  return stdDev;
};

