function invertTree(root) {
  if (!root) {
    console.log(`Encountered a null root. Returning null as per example 2.`);
    return null;
  }

  const stack = [root];
  console.log(`Starting tree inversion. Initial stack contains root with value: ${root.value}.`);

  while (stack.length > 0) {
    const node = stack.pop();
    console.log(`Processing node with value: ${node.value}.`);

    if (node.left || node.right) {
      console.log(`Swapping children for node ${node.value}.`);
      const temp = node.left;
      node.left = node.right;
      node.right = temp;
      console.log(`Children swapped. New left: ${node.left ? node.left.value : 'null'}, new right: ${node.right ? node.right.value : 'null'}.`);
    } else {
      console.log(`Node ${node.value} has no children to swap.`);
    }

    if (node.left) {
      stack.push(node.left);
      console.log(`Added left child ${node.left.value} to stack.`);
    }
    if (node.right) {
      stack.push(node.right);
      console.log(`Added right child ${node.right.value} to stack.`);
    }
  }

  console.log(`Tree inversion complete. Returning the modified root with value: ${root.value}.`);
  return root;
}

